def feature(s):
    v = s.get('volume_per_atom_A3')
    if v is None:
        v = s.get('basic_structure_statistics', {}).get('volume_per_atom_A3')
    if v is None or not math.isfinite(v) or v <= 0:
        return 0.0
    return float(math.log1p(v))

def feature(s):
    v = s.get('volume_per_atom_A3')
    if v is None:
        v = s.get('basic_structure_statistics', {}).get('volume_per_atom_A3')
    if v is None or not math.isfinite(v) or v <= 0:
        return 0.0
    p = s.get('element_properties', {})
    total = 0.0
    weight = 0.0
    for e, x in s.get('composition', {}).items():
        r = p.get(e, {}).get('covalent_radius_A')
        if x is not None and x > 0 and r is not None and math.isfinite(r) and r > 0:
            total += x * r ** 3
            weight += x
    if weight <= 0:
        return 0.0
    return float(4.0 * math.pi * total / (3.0 * weight * v))

def feature(s):
    v = s.get('volume_per_atom_A3')
    if v is None:
        v = s.get('basic_structure_statistics', {}).get('volume_per_atom_A3')
    if v is None or not math.isfinite(v) or v <= 0:
        return 0.0
    p = s.get('element_properties', {})
    total = 0.0
    weight = 0.0
    for e, x in s.get('composition', {}).items():
        q = p.get(e, {}).get('valence_electrons')
        if x is not None and x > 0 and q is not None and math.isfinite(q):
            total += x * q
            weight += x
    return float(total / (weight * v)) if weight > 0 else 0.0

def feature(s):
    sites = s.get('sites', ())
    n = len(sites)
    occ = [max(0.0, float(t.get('occupancy', 1.0) or 0.0)) for t in sites]
    nearest = [math.inf] * n
    for b in s.get('neighbors', ()):
        i = b['i']
        j = b['j']
        d = b.get('distance_A')
        if d is not None and d > 0 and occ[j] > 0 and d < nearest[i]:
            nearest[i] = d
    weight = sum(occ[i] for i in range(n) if math.isfinite(nearest[i]))
    if weight <= 0:
        return 0.0
    mean = sum(occ[i] * nearest[i] for i in range(n) if math.isfinite(nearest[i])) / weight
    if mean <= 0:
        return 0.0
    var = sum(occ[i] * (nearest[i] - mean) ** 2 for i in range(n) if math.isfinite(nearest[i])) / weight
    return float(math.sqrt(max(0.0, var)) / mean)
